const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const Q = '/home/node/.n8n/queue/publish';
const HANDS = '/home/node/hands-queue/inbox';
const LOGD = '/home/node/.n8n/logs';
for (const d of [Q, Q + '/done', Q + '/failed', LOGD, HANDS]) {
  try { fs.mkdirSync(d, { recursive: true }); } catch (e) {}
}
const token = ENV('TELEGRAM_BOT_TOKEN');
let chatId = null;
try { chatId = JSON.parse(fs.readFileSync('/home/node/.n8n/state/tg.json', 'utf8')).chat_id; } catch (e) {}
const tg = (m, b) => this.helpers.httpRequest({
  method: 'POST', url: 'https://api.telegram.org/bot' + token + '/' + m, body: b, json: true
});
const http = (o) => this.helpers.httpRequest(o);
const log = (r) => fs.appendFileSync(LOGD + '/publish.jsonl',
  JSON.stringify({ ts: new Date().toISOString(), ...r }) + '\n');

const RECIPE = {
  facebook: 'facebook_post',
  linkedin: 'linkedin_post',
  instagram: 'instagram_post',
  tiktok: 'tiktok_post'
};

async function publishTask(t) {
  const p = String(t.platform || '').toLowerCase();
  // VK personal wall via official API when the standalone token exists
  if (p === 'vk' && ENV('VK_ACCESS_TOKEN')) {
    const r = await http({
      method: 'GET', json: true,
      url: 'https://api.vk.com/method/wall.post?v=5.199&access_token=' +
        encodeURIComponent(ENV('VK_ACCESS_TOKEN')) +
        '&message=' + encodeURIComponent(t.text)
    });
    if (r && r.error) throw new Error('vk: ' + JSON.stringify(r.error).slice(0, 200));
    return 'vk api wall.post';
  }
  // LinkedIn Community Management API when the token exists, else hands-agent
  if (p === 'linkedin' && ENV('LINKEDIN_ACCESS_TOKEN') && ENV('LINKEDIN_PERSON_URN')) {
    await http({
      method: 'POST', url: 'https://api.linkedin.com/rest/posts',
      headers: {
        'Authorization': 'Bearer ' + ENV('LINKEDIN_ACCESS_TOKEN'),
        'X-Restli-Protocol-Version': '2.0.0'
      },
      body: {
        author: ENV('LINKEDIN_PERSON_URN'), commentary: t.text, visibility: 'PUBLIC',
        distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
        lifecycleState: 'PUBLISHED', isReshareDisabledByAuthor: false
      },
      json: true
    });
    return 'linkedin api';
  }
  // hands-agent driver: FB, IG, TikTok, LinkedIn fallback
  const recipe = RECIPE[p];
  if (!recipe) throw new Error('no driver for platform ' + p);
  fs.writeFileSync(HANDS + '/' + t.id + '.json', JSON.stringify({
    recipe: recipe,
    params: { text: t.text, image: t.image || '', image_path: t.image || '' }
  }, null, 2));
  return 'hands-agent queue (' + recipe + ')';
}

const out = [];
const files = fs.existsSync(Q) ? fs.readdirSync(Q).filter(f => f.endsWith('.json')) : [];
for (const f of files) {
  const file = Q + '/' + f;
  let t;
  try {
    t = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (e) {
    fs.renameSync(file, Q + '/failed/' + f);
    log({ file: f, error: 'bad json' });
    continue;
  }
  try {
    const via = await publishTask(t);
    fs.renameSync(file, Q + '/done/' + f);
    log({ id: t.id, platform: t.platform, via: via, status: 'queued' });
    out.push(t.id + ' ' + t.platform + ' -> ' + via);
  } catch (e) {
    fs.renameSync(file, Q + '/failed/' + f);
    log({ id: t.id, platform: t.platform, status: 'failed', error: String(e).slice(0, 300) });
    out.push(t.id + ' ' + t.platform + ' FAILED: ' + String(e).slice(0, 150));
  }
}
if (out.length && chatId && token) {
  try { await tg('sendMessage', { chat_id: chatId, text: 'Publish queue:\n' + out.join('\n') }); } catch (e) {}
}
return [{ json: { processed: out.length, results: out } }];
